using AcroFunJam.Application.Catalog;
using AcroFunJam.Domain.SharedKernel;
using AcroFunJam.Infrastructure.Photos;
using ImageMagick;
using ImageMagick.Drawing;

namespace AcroFunJam.Infrastructure.Tests.Photos;

/// <summary>
/// The processing of the images with Magick.NET (story 10, R4, R6, R10, ADR 0039): the format is recognised from the content,
/// the dimensions are given upright; the generated sizes are WebP, upright, without any metadata, never enlarged.
/// The files are generated by the test: no binary file is versioned.
/// </summary>
[Trait("Category", "Integration")]
public sealed class MagickPhotoProcessorTests
{
    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    private readonly MagickPhotoProcessor _processor = new();

    private static byte[] Photo(MagickFormat format, uint width, uint height, Action<MagickImage>? before = null)
    {
        using var image = new MagickImage(new MagickColor("#C8A27C"), width, height);
        image.Draw(new Drawables().FillColor(new MagickColor("#2F3F4C")).Rectangle(0, 0, width / 4.0, height / 2.0));
        before?.Invoke(image);
        return image.ToByteArray(format);
    }

    /// <summary>A JPEG with a position GPS and the model of the camera in its EXIF, marked « to be turned by 90° » (orientation 6).</summary>
    private static byte[] PhoneJpeg(uint width, uint height) => Photo(MagickFormat.Jpeg, width, height, image =>
    {
        var exif = new ExifProfile();
        exif.SetValue(ExifTag.Model, "Pixel 9");
        exif.SetValue(ExifTag.GPSLatitudeRef, "N");
        exif.SetValue(ExifTag.GPSLatitude, [new Rational(45, 1), new Rational(45, 1), new Rational(50, 1)]);
        exif.SetValue(ExifTag.Orientation, (ushort)6);
        image.SetProfile(exif);
        image.Orientation = ImageMagick.Orientation.RightTop;
    });

    [Theory]
    [InlineData(MagickFormat.Jpeg, PhotoFormat.Jpeg)]
    [InlineData(MagickFormat.Png, PhotoFormat.Png)]
    [InlineData(MagickFormat.WebP, PhotoFormat.WebP)]
    public async Task Probe_Should_RecogniseTheFormatAndTheDimensions_When_TheFileIsAnAcceptedPhoto(MagickFormat written, PhotoFormat expected)
    {
        var probe = await _processor.Probe(Photo(written, 1600, 1200), Ct);

        probe.ShouldBe(new PhotoProbe(expected, new PhotoDimensions(1600, 1200)));
    }

    [Fact]
    public async Task Probe_Should_RecogniseAHeicPhoto_When_TheEncoderIsAvailable()
    {
        byte[] heic;
        try
        {
            heic = Photo(MagickFormat.Heic, 1600, 1200);
        }
        catch (MagickException)
        {
            Assert.Skip("Magick.NET cannot encode HEIC here; reading is exercised on a real iPhone photo by hand.");
            return;
        }

        (await _processor.Probe(heic, Ct)).ShouldBe(new PhotoProbe(PhotoFormat.Heic, new PhotoDimensions(1600, 1200)));
    }

    [Fact]
    public async Task Probe_Should_FindNoAcceptedFormat_When_TheFileIsAnAnimatedGif()
    {
        using var frames = new MagickImageCollection();
        frames.Add(new MagickImage(MagickColors.Red, 800, 800));
        frames.Add(new MagickImage(MagickColors.Blue, 800, 800));

        (await _processor.Probe(frames.ToByteArray(MagickFormat.Gif), Ct)).Format.ShouldBeNull();
    }

    [Theory]
    [InlineData("%PDF-1.7\n1 0 obj << /Type /Catalog >> endobj")]
    [InlineData("Folded Leaf, notes de jam")]
    public async Task Probe_Should_FindNoAcceptedFormat_When_TheFileIsNotAPhoto(string content)
    {
        (await _processor.Probe(System.Text.Encoding.UTF8.GetBytes(content), Ct)).ShouldBe(new PhotoProbe(null, null));
    }

    /// <summary>Files crafted for ImageMagick (ImageTragick): never decoded, recognised from their first bytes only.</summary>
    [Theory]
    [InlineData("<?xml version=\"1.0\"?><svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" width=\"1600\" height=\"1200\"><image xlink:href=\"file:///etc/passwd\" width=\"1600\" height=\"1200\"/></svg>")]
    [InlineData("push graphic-context\nviewbox 0 0 1600 1200\nimage over 0,0 0,0 'file:///etc/passwd'\npop graphic-context")]
    [InlineData("text:/etc/passwd")]
    public async Task ProbeAndRender_Should_RefuseTheFile_When_ItIsCraftedForAnotherCoderOfImageMagick(string content)
    {
        var bytes = System.Text.Encoding.UTF8.GetBytes(content);

        (await _processor.Probe(bytes, Ct)).ShouldBe(new PhotoProbe(null, null));
        (await _processor.Render(bytes, Ct)).Error.ShouldBe(PhotoContentErrors.Unreadable);
    }

    [Fact]
    public async Task Probe_Should_FindNoAcceptedFormat_When_TheFileIsAnAvifPhoto()
    {
        byte[] avif;
        try
        {
            avif = Photo(MagickFormat.Avif, 1600, 1200);
        }
        catch (MagickException)
        {
            Assert.Skip("Magick.NET cannot encode AVIF here.");
            return;
        }

        (await _processor.Probe(avif, Ct)).Format.ShouldBeNull();
    }

    [Fact]
    public async Task Probe_Should_GiveTheUprightDimensions_When_TheJpegIsMarkedToBeTurned()
    {
        (await _processor.Probe(PhoneJpeg(1600, 1200), Ct)).Dimensions.ShouldBe(new PhotoDimensions(1200, 1600));
    }

    [Fact]
    public async Task Render_Should_GenerateTheThreeSizesInWebP_When_ThePhotoIsReadable()
    {
        var renditions = (await _processor.Render(Photo(MagickFormat.Png, 3000, 2000), Ct)).Value!;

        Size(renditions, PhotoRendition.Thumbnail).ShouldBe((192u, 192u));
        Size(renditions, PhotoRendition.Page).ShouldBe((1200u, 800u));
        Size(renditions, PhotoRendition.Enlarged).ShouldBe((2400u, 1600u));
        foreach (var rendition in renditions.All)
        {
            using var image = new MagickImage(rendition.Content.ToArray());
            image.Format.ShouldBe(MagickFormat.WebP);
            ((uint)rendition.Width, (uint)rendition.Height).ShouldBe((image.Width, image.Height));
        }
    }

    [Fact]
    public async Task Render_Should_KeepTheWholePhotoOnTransparentMargins_When_TheThumbnailIsSquare()
    {
        var thumbnail = (await _processor.Render(Photo(MagickFormat.Jpeg, 800, 1200), Ct)).Value!.Of(PhotoRendition.Thumbnail);

        using var image = new MagickImage(thumbnail.Content.ToArray());
        image.HasAlpha.ShouldBeTrue();
        image.GetPixels().GetPixel(0, 96)!.ToColor()!.A.ShouldBe((byte)0);
        image.GetPixels().GetPixel(96, 96)!.ToColor()!.A.ShouldBe((byte)255);
    }

    [Fact]
    public async Task Render_Should_NeverEnlargeThePhoto_When_ItIsSmallerThanASize()
    {
        var renditions = (await _processor.Render(Photo(MagickFormat.Jpeg, 1000, 800), Ct)).Value!;

        Size(renditions, PhotoRendition.Page).ShouldBe((1000u, 800u));
        Size(renditions, PhotoRendition.Enlarged).ShouldBe((1000u, 800u));
    }

    [Fact]
    public async Task Render_Should_TurnThePhotoUprightAndRemoveEveryMetadata_When_TheJpegComesFromAPhone()
    {
        var renditions = (await _processor.Render(PhoneJpeg(1600, 1200), Ct)).Value!;

        Size(renditions, PhotoRendition.Page).ShouldBe((900u, 1200u));
        foreach (var rendition in renditions.All)
        {
            using var image = new MagickImage(rendition.Content.ToArray());
            image.GetExifProfile().ShouldBeNull();
            image.GetXmpProfile().ShouldBeNull();
            image.Orientation.ShouldBeOneOf(ImageMagick.Orientation.Undefined, ImageMagick.Orientation.TopLeft);
            System.Text.Encoding.Latin1.GetString(rendition.Content.Span).ShouldNotContain("Pixel 9");
        }
    }

    [Fact]
    public async Task Render_Should_FailWithUnreadable_When_TheFileIsTruncated()
    {
        var truncated = Photo(MagickFormat.Jpeg, 1600, 1200)[..200];

        (await _processor.Render(truncated, Ct)).Error.ShouldBe(PhotoContentErrors.Unreadable);
    }

    private static (uint Width, uint Height) Size(PhotoRenditions renditions, PhotoRendition rendition)
    {
        var rendered = renditions.Of(rendition);
        return ((uint)rendered.Width, (uint)rendered.Height);
    }
}
